#[cfg(test)]
mod tests {
    /// Strictly ascending: binary search demands it, and it doubles as
    /// a dedup check.
    #[test]
    fn table_is_sorted_by_spell_id() {
        assert!(super::TABLE.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(super::TRINKETS.windows(2).all(|w| w[0].0 < w[1].0));
        let names = super::NAMES.len();
        assert!(super::TRINKETS.iter().all(|t| (t.2 as usize) < names));
    }
}
